import os, stat, json, hashlib, pathlib
from pathlib import Path

work=Path('/work')
claude=work/'CLAUDE.md'
agents=work/'AGENTS.md'

report={}

def path_info(p:Path):
    info={'path':str(p), 'exists':p.exists(), 'lexists':os.path.lexists(p)}
    try:
        st=os.lstat(p)
        info.update({
            'mode_octal': oct(st.st_mode & 0o7777),
            'uid': st.st_uid,
            'gid': st.st_gid,
            'is_symlink': stat.S_ISLNK(st.st_mode),
            'is_regular': stat.S_ISREG(st.st_mode),
            'size': st.st_size,
        })
        if stat.S_ISLNK(st.st_mode):
            try:
                info['readlink']=os.readlink(p)
            except Exception as e:
                info['readlink_error']=repr(e)
    except FileNotFoundError:
        info['lstat_error']='FileNotFoundError'
    except Exception as e:
        info['lstat_error']=repr(e)
    return info

report['before']={'work':path_info(work), 'claude':path_info(claude), 'agents':path_info(agents)}

# Read CLAUDE.md bytes if possible
claude_bytes=None
try:
    claude_bytes=claude.read_bytes()
    report['read_claude']={'ok':True,'bytes':len(claude_bytes),'sha256':hashlib.sha256(claude_bytes).hexdigest()}
except Exception as e:
    report['read_claude']={'ok':False,'error':repr(e)}

# Write AGENTS.md as regular file preserving bytes
if claude_bytes is not None:
    try:
        # Ensure AGENTS path is not a symlink/non-regular obstacle
        if os.path.lexists(agents):
            st=os.lstat(agents)
            if stat.S_ISLNK(st.st_mode):
                # remove symlink first
                os.unlink(agents)
            elif not stat.S_ISREG(st.st_mode):
                raise RuntimeError(f'AGENTS.md exists and is not regular file, mode {oct(st.st_mode)}')
        with open(agents,'wb') as f:
            f.write(claude_bytes)
        report['write_agents']={'ok':True}
    except Exception as e:
        report['write_agents']={'ok':False,'error':repr(e)}

# Verify AGENTS bytes
try:
    b=agents.read_bytes()
    report['verify_agents']={'ok':True,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'matches_claude':(claude_bytes is not None and b==claude_bytes)}
except Exception as e:
    report['verify_agents']={'ok':False,'error':repr(e)}

# Attempt removal of CLAUDE.md entry
try:
    os.unlink(claude)
    report['remove_claude']={'ok':True}
except Exception as e:
    report['remove_claude']={'ok':False,'error_type':type(e).__name__,'error':str(e)}

report['after']={'claude':path_info(claude), 'agents':path_info(agents)}

print(json.dumps(report, indent=2, sort_keys=True))

